/* The clock only reveals precomputed fixed-time simulation steps. */
(() => {
  'use strict';
  const $ = id => document.getElementById(id), A = window.Abyss;
  const svgNS = 'http://www.w3.org/2000/svg';
  const titles = { nominal: 'The quiet-water expedition', dropout: 'Into the dark', current: 'An unseen current', bias: 'A convincing lie' };
  let config = { ...A.defaults }, data, rows, index = 0, timer = null, comparison = null, domain;
  const fmt = (n, digits = 2) => n === null || n === undefined ? '—' : n.toFixed(digits);
  const announce = text => { $('announcement').textContent = text; };
  function node(name, attrs, text) {
    const e = document.createElementNS(svgNS, name);
    for (const [key, value] of Object.entries(attrs)) e.setAttribute(key, value);
    if (text) e.textContent = text;
    return e;
  }
  function limits() {
    const values = rows.flatMap(r => [r.truth, r.dr, r.z === null ? r.truth : r.z, r.x[0] - 2 * Math.sqrt(r.P[0][0]), r.x[0] + 2 * Math.sqrt(r.P[0][0])]);
    // Axis remains fixed throughout a replay, including the comparison.
    domain = [Math.floor((Math.min(0, ...values) - 1) / 2) * 2, Math.ceil((Math.max(12, ...values) + 1) / 2) * 2];
  }
  const X = t => 60 + t / 60 * 740;
  const Y = depth => 50 + (depth - domain[0]) / (domain[1] - domain[0]) * 244;
  const point = (t, depth) => `${X(t).toFixed(2)},${Y(depth).toFixed(2)}`;
  const path = (items, value) => items.map((d, i) => `${i ? 'L' : 'M'}${point(d.t, value(d))}`).join(' ');
  function axes() {
    $('axes').replaceChildren(); $('checkpoints').replaceChildren();
    for (let i = 0; i <= 4; i++) {
      const depth = domain[0] + (domain[1] - domain[0]) * i / 4, y = Y(depth);
      $('axes').append(node('line', { x1: 60, x2: 800, y1: y, y2: y, stroke: '#9abbb5', 'stroke-opacity': '.13' }), node('text', { x: 45, y: y + 4, fill: '#bed3cf', 'font-size': 10, 'text-anchor': 'end' }, `${fmt(depth, 0)} m`));
    }
    for (const t of [0, 15, 30, 45, 60]) $('axes').append(node('text', { x: X(t), y: 320, fill: '#bed3cf', 'font-size': 10, 'text-anchor': 'middle' }, `${t} s`));
    for (const [t, label, depth] of [[15, 'GATE', 6.7], [35, 'SLALOM', 9.5], [60, 'BIN', 7]]) {
      $('checkpoints').append(node('line', { x1: X(t), x2: X(t), y1: 37, y2: 294, stroke: '#9abbb5', 'stroke-opacity': '.2', 'stroke-dasharray': '2 5' }), node('text', { x: X(t), y: 27, fill: '#9cbcb6', 'font-size': 9, 'text-anchor': 'middle', 'letter-spacing': 2 }, label));
      if (t < 60) $('checkpoints').append(node('path', { d: `M${X(t) - 9} ${Y(depth) + 13}v-26h18v26`, fill: 'none', stroke: '#96b9a1', 'stroke-opacity': '.5', 'stroke-width': 3 }));
      else $('checkpoints').append(node('path', { d: `M${X(t) - 12} ${Y(depth) - 5}v14h24v-14`, fill: 'none', stroke: '#96b9a1', 'stroke-opacity': '.5', 'stroke-width': 3 }));
    }
    if (config.scenario === 'dropout') $('axes').append(node('rect', { x: X(20), y: 50, width: X(38) - X(20), height: 244, fill: '#000', opacity: '.12' }), node('text', { x: X(29), y: 45, fill: '#f4a77f', 'font-size': 9, 'text-anchor': 'middle' }, 'FIX BLACKOUT'));
  }
  function render() {
    const visible = rows.slice(0, index + 1), d = rows[index], m = A.metrics(visible), sigma = Math.sqrt(d.P[0][0]);
    $('truth-trace').setAttribute('d', path(visible, r => r.truth));
    $('estimate-trace').setAttribute('d', path(visible, r => r.x[0]));
    $('dr-trace').setAttribute('d', path(visible, r => r.dr));
    $('comparison-trace').setAttribute('d', comparison ? path(comparison.rows.slice(0, index + 1), r => r.x[0]) : '');
    const upper = path(visible, r => r.x[0] - 2 * Math.sqrt(r.P[0][0]));
    const lower = [...visible].reverse().map(r => `L${point(r.t, r.x[0] + 2 * Math.sqrt(r.P[0][0]))}`).join(' ');
    $('band').setAttribute('d', `${upper} ${lower} Z`);
    $('fixes').replaceChildren(); $('estimate-points').replaceChildren();
    for (const r of visible.slice(1)) {
      if (r.z !== null) { const x = X(r.t), y = Y(r.z); $('fixes').append(node('path', { d: `M${x - 3} ${y - 3}l6 6m-6 0l6-6` })); }
      if (Math.round(r.t * 2) % 8 === 0 || r === d) $('estimate-points').append(node('circle', { cx: X(r.t), cy: Y(r.x[0]), r: 3 }));
    }
    $('sub').setAttribute('transform', `translate(${X(d.t)} ${Y(d.truth)})`);
    $('clock').textContent = `${d.t.toFixed(1).padStart(4, '0')} / 60.0 s`;
    $('scene-status').textContent = index === 0 ? 'Awaiting departure' : index === A.STEPS ? 'Expedition complete' : d.event;
    $('mission-progress').value = index;
    $('truth-value').innerHTML = `${fmt(d.truth)} <small>m</small>`;
    $('fix-value').innerHTML = d.z === null ? '—' : `${fmt(d.z)} <small>m</small>`;
    $('estimate-value').innerHTML = `${fmt(d.x[0])} <small>m</small>`;
    $('uncertainty-value').innerHTML = `${fmt(2 * sigma)} <small>m</small>`;
    $('raw-rmse').textContent = m.raw === null ? '—' : `${fmt(m.raw)} m`;
    $('filter-rmse').textContent = m.filter === null ? '—' : `${fmt(m.filter)} m`;
    $('dr-rmse').textContent = m.dr === null ? '—' : `${fmt(m.dr)} m`;
    $('sample-count').textContent = `${m.fixes} fixes · ${index} steps`;
    const error = Math.abs(d.x[0] - d.truth);
    $('plot-equivalent').textContent = `At ${fmt(d.t, 1)} s: truth ${fmt(d.truth)} m; ${d.z === null ? 'no localization fix' : `fix ${fmt(d.z)} m`}; estimate ${fmt(d.x[0])} m; velocity ${fmt(d.x[1])} m/s. Modeled depth interval ${fmt(d.x[0] - 2 * sigma)}–${fmt(d.x[0] + 2 * sigma)} m. Actual error ${fmt(error)} m. ${d.event}.`;
    $('plot-description').textContent = $('plot-equivalent').textContent + ' Time increases to the right and depth increases downward. Shapes and colors are described in the legend.';
    $('worked-prior').textContent = `${fmt(d.prior ? d.prior.x[0] : d.x[0])} m`;
    $('worked-result').textContent = `${fmt(d.x[0])} m`;
    $('worked-intro').textContent = index === 0 ? 'Take one step to inspect a real correction. Each step represents 0.5 seconds.' : d.z === null ? `At ${fmt(d.t, 1)} s, the fix is missing. Skip correction: the prediction becomes the estimate and uncertainty grows.` : `At ${fmt(d.t, 1)} s, the fix is ${fmt(d.z)} m. The gain decides how far the prediction moves toward it.`;
    $('worked-adjustment').textContent = index === 0 ? 'Waiting for a fix' : d.z === null ? 'No fix → +0.00 m' : `${fmt(d.K[0], 3)} × ${fmt(d.innovation)} m`;
    $('worked-velocity').textContent = index === 0 ? 'The filter also estimates velocity in m/s.' : `Velocity correction uses gain ${fmt(d.K[1], 3)} s⁻¹. Estimated velocity: ${fmt(d.x[1], 3)} m/s. Depth variance P₀₀ = ${fmt(d.P[0][0], 3)} m².`;
    $('field-tip').textContent = index === 0 ? 'The sub icon marks ground truth. The filter never gets to see it. Watch the mint estimate learn from the orange fixes.' : d.z === null ? 'Into the dark: there is no orange fix to pull the estimate back. Every prediction adds motion uncertainty. Watch the mint band widen until fixes return at 38 seconds.' : config.scenario === 'bias' && d.t >= 20 ? 'A convincing lie: the fixes are now 2.5 m too deep. The filter can become confidently wrong. Compare its modeled interval with the white truth trace.' : config.scenario === 'current' && d.t >= 18 ? 'An unseen current: the real sub has an extra acceleration from 18–32 s. The filter knows only the command. Sensor corrections help it recover; Q controls how much it doubts its motion model.' : 'The orange cross is an observation, not a destination. The mint estimate balances that fix with the motion prediction. More trust in the sensor means a larger correction.';
    $('step').disabled = index === A.STEPS;
    $('summary').hidden = index !== A.STEPS;
    if (index === A.STEPS) {
      $('summary').innerHTML = `<h4>Expedition complete. What did you learn?</h4><p>Final actual error: <b>${fmt(error)} m</b>. Modeled ±2σ: <b>${fmt(2 * sigma)} m</b>. Truth was inside the band for <b>${fmt(m.coverage * 100, 0)}%</b> of steps.</p><p>${config.scenario === 'bias' ? 'Persistent bias is outside this model. Confidence can be misplaced.' : config.scenario === 'dropout' ? 'Without fixes, prediction carried the mission. Uncertainty grew, then contracted when fixes returned.' : config.scenario === 'current' ? 'Unmodeled motion challenged the prediction. Corrections helped the estimate follow the current.' : 'The model and sensor shared the work. Try a dropout next to see what happens when one goes quiet.'}</p><p>Reset replays this exact seed. Compare tuning to keep the ocean identical.</p>`;
    }
  }
  function pause() { if (timer !== null) window.clearInterval(timer); timer = null; $('play').textContent = index === A.STEPS ? '↺ Replay mission' : index === 0 ? '▶ Start mission' : '▶ Continue'; }
  function advance() { if (index < A.STEPS) index++; render(); if (index === A.STEPS) { pause(); announce('Expedition complete. The mission log now contains your final errors and uncertainty coverage.'); } }
  function reset() { pause(); index = 0; render(); $('play').textContent = '▶ Start mission'; }
  function labels() {
    $('actual-label').textContent = `σ = ${fmt(Number($('actual').value))} m`;
    $('r-label').textContent = `σ = ${fmt(Number($('assumed-r').value))} m`;
    $('q-label').textContent = `σ = ${fmt(Number($('assumed-q').value))} m/s²`;
    $('variance-note').textContent = `R = ${fmt(Number($('assumed-r').value) ** 2)} m². Q comes from acceleration variance ${fmt(Number($('assumed-q').value) ** 2, 4)} (m/s²)².`;
  }
  function apply() {
    if (!$('seed').checkValidity()) { $('seed').reportValidity(); return; }
    config = { seed: Number($('seed').value), scenario: document.querySelector('input[name=scenario]:checked').value, actualSensor: Number($('actual').value), assumedSensor: Number($('assumed-r').value), assumedAccel: Number($('assumed-q').value) };
    data = A.makeData(config); rows = A.run(data, config); comparison = null;
    $('comparison-output').hidden = true;
    $('mission-title').textContent = titles[config.scenario];
    limits(); axes(); reset();
    $('settings-note').textContent = `Applied: ${config.scenario}, seed ${config.seed}. Ready to replay.`;
    announce('Settings applied. Mission reset and paused.');
  }
  for (const id of ['actual', 'assumed-r', 'assumed-q', 'seed']) $(id).addEventListener('input', () => { labels(); $('settings-note').textContent = 'Unapplied changes. Use “Apply & reset” to start with these settings.'; });
  document.querySelectorAll('input[name=scenario]').forEach(r => r.addEventListener('change', apply));
  $('apply').addEventListener('click', apply);
  $('play').addEventListener('click', () => { if (timer !== null) { pause(); announce('Mission paused.'); return; } if (index === A.STEPS) reset(); timer = window.setInterval(advance, 150); $('play').textContent = 'Ⅱ Pause'; announce('Mission running.'); });
  $('step').addEventListener('click', () => { pause(); advance(); announce(`Stepped to ${rows[index].t} seconds. ${rows[index].event}.`); });
  $('reset').addEventListener('click', () => { reset(); announce('Mission reset. The seed and sensor stream are unchanged.'); });
  $('compare').addEventListener('click', () => {
    if (!$('compare-r').checkValidity()) { $('compare-r').reportValidity(); return; }
    const sigma = Number($('compare-r').value), alternate = A.run(data, { ...config, assumedSensor: sigma }), a = A.metrics(rows), b = A.metrics(alternate);
    comparison = { rows: alternate, sigma }; pause();
    const output = $('comparison-output'); output.hidden = false;
    output.innerHTML = `<table><caption>Full 60 s replay · seed ${config.seed}</caption><thead><tr><th scope="col">Depth RMSE</th><th scope="col">Applied</th><th scope="col">Alternative</th></tr></thead><tbody><tr><th scope="row">R (m²)</th><td>${fmt(config.assumedSensor ** 2)}</td><td>${fmt(sigma ** 2)}</td></tr><tr><th scope="row">Filter (m)</th><td>${fmt(a.filter)}</td><td>${fmt(b.filter)}</td></tr><tr><th scope="row">Raw fix (m)</th><td>${fmt(a.raw)}</td><td>${fmt(b.raw)}</td></tr></tbody></table><p class="compare-key">┄ Gold dashes: alternative estimate, revealed as you step or play.</p><p>Same ${a.fixes} fixes, same truth, same Q. ${b.filter < a.filter ? 'The alternative has a lower RMSE on this seed.' : b.filter > a.filter ? 'The applied tuning has a lower RMSE on this seed.' : 'The RMSE is unchanged.'} A single replay does not prove one tuning is always better.</p>`;
    render(); announce('Full mission comparison ready. Both filters used identical sensor data.');
  });
  document.addEventListener('visibilitychange', () => { if (document.hidden && timer !== null) pause(); });
  ['play', 'step', 'reset', 'apply', 'compare'].forEach(id => { $(id).disabled = false; });
  labels(); apply();
})();

