diff --git a/kalman/app.js b/kalman/app.js
new file mode 100644
index 0000000000000000000000000000000000000000..4990d209fd7cceae24dbba02f2f77dcc3c399fb0
--- /dev/null
+++ b/kalman/app.js
@@ -0,0 +1,116 @@
+/* The clock only reveals precomputed fixed-time simulation steps. */
+(() => {
+  'use strict';
+  const $ = id => document.getElementById(id), A = window.Abyss;
+  const svgNS = 'http://www.w3.org/2000/svg';
+  const titles = { nominal: 'The quiet-water expedition', dropout: 'Into the dark', current: 'An unseen current', bias: 'A convincing lie' };
+  let config = { ...A.defaults }, data, rows, index = 0, timer = null, comparison = null, domain;
+  const fmt = (n, digits = 2) => n === null || n === undefined ? '—' : n.toFixed(digits);
+  const announce = text => { $('announcement').textContent = text; };
+  function node(name, attrs, text) {
+    const e = document.createElementNS(svgNS, name);
+    for (const [key, value] of Object.entries(attrs)) e.setAttribute(key, value);
+    if (text) e.textContent = text;
+    return e;
+  }
+  function limits() {
+    const values = rows.flatMap(r => [r.truth, r.dr, r.z === null ? r.truth : r.z, r.x[0] - 2 * Math.sqrt(r.P[0][0]), r.x[0] + 2 * Math.sqrt(r.P[0][0])]);
+    // Axis remains fixed throughout a replay, including the comparison.
+    domain = [Math.floor((Math.min(0, ...values) - 1) / 2) * 2, Math.ceil((Math.max(12, ...values) + 1) / 2) * 2];
+  }
+  const X = t => 60 + t / 60 * 740;
+  const Y = depth => 50 + (depth - domain[0]) / (domain[1] - domain[0]) * 244;
+  const point = (t, depth) => `${X(t).toFixed(2)},${Y(depth).toFixed(2)}`;
+  const path = (items, value) => items.map((d, i) => `${i ? 'L' : 'M'}${point(d.t, value(d))}`).join(' ');
+  function axes() {
+    $('axes').replaceChildren(); $('checkpoints').replaceChildren();
+    for (let i = 0; i <= 4; i++) {
+      const depth = domain[0] + (domain[1] - domain[0]) * i / 4, y = Y(depth);
+      $('axes').append(node('line', { x1: 60, x2: 800, y1: y, y2: y, stroke: '#9abbb5', 'stroke-opacity': '.13' }), node('text', { x: 45, y: y + 4, fill: '#bed3cf', 'font-size': 10, 'text-anchor': 'end' }, `${fmt(depth, 0)} m`));
+    }
+    for (const t of [0, 15, 30, 45, 60]) $('axes').append(node('text', { x: X(t), y: 320, fill: '#bed3cf', 'font-size': 10, 'text-anchor': 'middle' }, `${t} s`));
+    for (const [t, label, depth] of [[15, 'GATE', 6.7], [35, 'SLALOM', 9.5], [60, 'BIN', 7]]) {
