+/* A two-state linear Kalman filter. No rendering, clock, or truth dependencies. */
+(function (root, factory) {
+  const api = factory();
+  if (typeof module === 'object' && module.exports) module.exports = api;
+  else root.Abyss = api;
+})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
+  'use strict';
+  const DT = 0.5, STEPS = 120;
+  const defaults = { seed: 42, scenario: 'nominal', actualSensor: 1.2, assumedSensor: 1.2, assumedAccel: 0.08 };
+  function predict(x, P, h, u, sigmaA) {
+    const g0 = h * h / 2, g1 = h, q = sigmaA * sigmaA;
+    return {
+      x: [x[0] + h * x[1] + g0 * u, x[1] + g1 * u],
+      P: [[P[0][0] + h * (P[0][1] + P[1][0]) + h * h * P[1][1] + q * g0 * g0,
+        P[0][1] + h * P[1][1] + q * g0 * g1],
+      [P[1][0] + h * P[1][1] + q * g1 * g0, P[1][1] + q * g1 * g1]]
+    };
+  }
+  function correct(prior, z, R) {
+    if (z === null) return { x: prior.x.slice(), P: prior.P.map(row => row.slice()), K: [0, 0], innovation: null };
+    const { x, P } = prior;
+    const S = P[0][0] + R, K = [P[0][0] / S, P[1][0] / S];
+    const innovation = z - x[0];
+    // Joseph form: (I-KH) P (I-KH)^T + K R K^T, H = [1, 0].
+    const A = [[1 - K[0], 0], [-K[1], 1]];
+    const covariance = Array.from({ length: 2 }, () => [0, 0]);
+    for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
+      for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) covariance[i][j] += A[i][a] * P[a][b] * A[j][b];
+      covariance[i][j] += K[i] * R * K[j];
+    }
+    covariance[0][1] = covariance[1][0] = (covariance[0][1] + covariance[1][0]) / 2;
+    return { x: [x[0] + K[0] * innovation, x[1] + K[1] * innovation], P: covariance, K, innovation };
+  }
+  function seeded(seed) {
+    let state = seed >>> 0;
+    return () => {
+      state += 0x6D2B79F5;
+      let n = state;
+      n = Math.imul(n ^ n >>> 15, n | 1);
+      n ^= n + Math.imul(n ^ n >>> 7, n | 61);
+      return ((n ^ n >>> 14) >>> 0) / 4294967296;
+    };
+  }
