new file mode 100644
index 0000000000000000000000000000000000000000..d7b64eedf78fafbe3e28db089e64763647407a5a
--- /dev/null
+++ b/tests/kalman-preview.cjs
@@ -0,0 +1,15 @@
+// A dependency-free static preview. Bound locally; never serves outside this checkout.
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+const root = path.resolve(__dirname, '..');
+const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.png': 'image/png', '.svg': 'image/svg+xml' };
+http.createServer((req, res) => {
+  try {
+    let relative = decodeURIComponent(new URL(req.url, 'http://localhost').pathname).replace(/^\//, '');
+    if (!relative || relative.endsWith('/')) relative += 'index.html';
+    const file = path.resolve(root, relative);
+    if (!file.startsWith(root + path.sep)) { res.writeHead(403); res.end(); return; }
+    fs.readFile(file, (err, content) => { res.writeHead(err ? 404 : 200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream' }); res.end(err ? 'Not found' : content); });
+  } catch { res.writeHead(400); res.end('Bad request'); }
+}).listen(8311, '127.0.0.1', () => console.log('Clarity preview: http://localhost:8311/kalman/'));
diff --git a/tests/kalman.test.cjs b/tests/kalman.test.cjs
new file mode 100644
index 0000000000000000000000000000000000000000..c748df4408e906331c7a04ffeea78e9fda1d38e8
--- /dev/null
+++ b/tests/kalman.test.cjs
@@ -0,0 +1,78 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const A = require('../kalman/filter.js');
+const near = (a, b, epsilon = 1e-12) => assert.ok(Math.abs(a - b) < epsilon, `${a} ≠ ${b}`);
+
+test('exact h=1 Kalman fixture with Joseph covariance', () => {
+  const prior = A.predict([0, 0], [[1, 0], [0, 1]], 1, 0, 0);
+  const result = A.correct(prior, 3, 1);
+  result.x.forEach((v, i) => near(v, [2, 1][i]));
+  result.K.forEach((v, i) => near(v, [2/3, 1/3][i]));
+  [[2/3, 1/3], [1/3, 2/3]].forEach((row, i) => row.forEach((v, j) => near(result.P[i][j], v)));
+});
+test('known acceleration and discrete acceleration Q have consistent units', () => {
+  const p = A.predict([2, 3], [[0, 0], [0, 0]], 2, 4, 0.5);
+  assert.deepEqual(p.x, [16, 11]);
+  assert.deepEqual(p.P, [[1, 1], [1, 1]]);
+});
+test('dropout performs prediction only and grows uncertainty until fixes resume', () => {
+  const config = { ...A.defaults, scenario: 'dropout' }, rows = A.run(A.makeData(config), config);
+  const lost = rows.filter(d => d.t >= 20 && d.t < 38);
+  assert.equal(lost.length, 36);
+  for (const d of lost) {
+    assert.equal(d.z, null); assert.deepEqual(d.x, d.prior.x); assert.deepEqual(d.P, d.prior.P);
+    assert.equal(d.innovation, null); assert.deepEqual(d.K, [0, 0]);
+  }
+  assert.ok(lost.at(-1).P[0][0] > lost[0].P[0][0]);
+  assert.ok(rows.find(d => d.t === 38).P[0][0] < lost.at(-1).P[0][0]);
+});
+test('replay is deterministic and tuning cannot change any truth or fix', () => {
+  for (const scenario of ['nominal', 'dropout', 'current', 'bias']) {
+    const config = { ...A.defaults, scenario }, d = A.makeData(config);
+    assert.deepEqual(d, A.makeData(config));
+    assert.deepEqual(d, A.makeData({ ...config, assumedSensor: 4, assumedAccel: 0.4 }));
+    assert.deepEqual(A.run(d, config), A.run(d, config));
+    const alt = A.run(d, { ...config, assumedSensor: 4 });
+    assert.deepEqual(alt.map(r => [r.truth, r.z]), d.map(r => [r.truth, r.z]));
+    assert.notDeepEqual(alt.map(r => r.x), A.run(d, config).map(r => r.x));
+  }
+  assert.notDeepEqual(A.makeData({ seed: 42 }), A.makeData({ seed: 43 }));
+});
+test('filter updates ignore truth and dead-reckoning values', () => {
+  const data = A.makeData(A.defaults), poisoned = data.map(d => ({ ...d, truth: 100000, trueVelocity: -9000 }));
+  assert.deepEqual(A.run(data, A.defaults).map(d => [d.x, d.P]), A.run(poisoned, A.defaults).map(d => [d.x, d.P]));
+});
+test('scenario disturbances are isolated and explicitly modeled as mismatches', () => {
+  const nominal = A.makeData(A.defaults), biased = A.makeData({ scenario: 'bias' }), current = A.makeData({ scenario: 'current' });
+  for (let i = 1; i < nominal.length; i++) {
+    near(biased[i].truth, nominal[i].truth);
+    near(biased[i].z - nominal[i].z, biased[i].t >= 20 ? 2.5 : 0);
+  }
+  near(current.find(d => d.t === 17.5).truth, nominal.find(d => d.t === 17.5).truth);
+  assert.ok(current.at(-1).truth > nominal.at(-1).truth + 5);
+});
+test('covariance remains finite symmetric and PSD over 10000 updates including dropouts', () => {
+  for (const [q, r] of [[0, 0.04], [0.01, 16], [0.4, 0.04]]) {
+    let x = [4, 0.05], P = [[1, 0], [0, 0.25]];
+    for (let k = 0; k < 10000; k++) {
+      const d = A.correct(A.predict(x, P, 0.5, 0.02 * Math.cos(k), q), k % 100 < 30 ? null : 8 + Math.sin(k), r);
+      x = d.x; P = d.P;
+      assert.ok([...x, ...P.flat()].every(Number.isFinite));
+      near(P[0][1], P[1][0]);
+      assert.ok(P[0][0] >= 0 && P[1][1] >= 0 && P[0][0] * P[1][1] - P[0][1] ** 2 >= -1e-10);
+    }
+  }
+});
+test('fixed seed mission metrics are finite and meaningful, not always improved', () => {
+  for (const scenario of ['nominal', 'dropout', 'current', 'bias']) {
+    const config = { ...A.defaults, scenario }, rows = A.run(A.makeData(config), config), m = A.metrics(rows);
+    assert.equal(rows.length, 121); assert.equal(rows.at(-1).t, 60);
+    assert.ok([m.raw, m.filter, m.dr].every(v => Number.isFinite(v) && v > 0));
