+      [P[1][0] + h * P[1][1] + q * g1 * g0, P[1][1] + q * g1 * g1]]
+    };
+  }
+  function correct(prior, z, R) {
+    if (z === null) return { x: prior.x.slice(), P: prior.P.map(row => row.slice()), K: [0, 0], innovation: null };
+    const { x, P } = prior;
+    const S = P[0][0] + R, K = [P[0][0] / S, P[1][0] / S];
+    const innovation = z - x[0];
+    // Joseph form: (I-KH) P (I-KH)^T + K R K^T, H = [1, 0].
+    const A = [[1 - K[0], 0], [-K[1], 1]];
+    const covariance = Array.from({ length: 2 }, () => [0, 0]);
+    for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
+      for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) covariance[i][j] += A[i][a] * P[a][b] * A[j][b];
+      covariance[i][j] += K[i] * R * K[j];
+    }
+    covariance[0][1] = covariance[1][0] = (covariance[0][1] + covariance[1][0]) / 2;
+    return { x: [x[0] + K[0] * innovation, x[1] + K[1] * innovation], P: covariance, K, innovation };
+  }
+  function seeded(seed) {
+    let state = seed >>> 0;
+    return () => {
+      state += 0x6D2B79F5;
+      let n = state;
+      n = Math.imul(n ^ n >>> 15, n | 1);
+      n ^= n + Math.imul(n ^ n >>> 7, n | 61);
+      return ((n ^ n >>> 14) >>> 0) / 4294967296;
+    };
+  }
+  function normal(rng) {
+    return Math.sqrt(-2 * Math.log(Math.max(rng(), 1e-12))) * Math.cos(2 * Math.PI * rng());
+  }
+  function makeData(config) {
+    const c = { ...defaults, ...config }, rng = seeded(c.seed);
+    let depth = 4, velocity = 0.05;
+    const data = [{ t: 0, truth: depth, trueVelocity: velocity, z: null, u: 0, event: 'Ready to dive' }];
+    for (let k = 1; k <= STEPS; k++) {
+      const t = k * DT;
+      const u = 2 * Math.pow(2 * Math.PI / 60, 2) * Math.cos(2 * Math.PI * (t - DT) / 60);
+      const accelerationNoise = 0.08 * normal(rng);
+      // Consume sensor randomness even during dropout. Tuning never enters this generator.
+      const sensorNoise = c.actualSensor * normal(rng);
+      const current = c.scenario === 'current' && t >= 18 && t < 32 ? 0.012 : 0;
+      const bias = c.scenario === 'bias' && t >= 20 ? 2.5 : 0;
+      const dropout = c.scenario === 'dropout' && t >= 20 && t < 38;
+      const a = u + accelerationNoise + current;
+      depth += DT * velocity + 0.5 * DT * DT * a;
+      velocity += DT * a;
+      data.push({ t, truth: depth, trueVelocity: velocity, z: dropout ? null : depth + sensorNoise + bias, u,
+        event: dropout ? 'Fix lost · prediction only' : current ? 'Unmodeled current active' : bias ? 'Fix biased +2.5 m' : 'Localization fix received' });
+    }
+    return data;
+  }
+  function run(data, config) {
+    const c = { ...defaults, ...config };
+    let x = [4, 0.05], P = [[1, 0], [0, 0.25]], dr = x.slice();
+    const rows = [{ ...data[0], x: x.slice(), P: P.map(r => r.slice()), dr: dr[0], K: [0, 0], innovation: null, prior: null }];
+    for (const d of data.slice(1)) {
+      const prior = predict(x, P, DT, d.u, c.assumedAccel);
+      const posterior = correct(prior, d.z, c.assumedSensor ** 2);
+      dr = predict(dr, [[0, 0], [0, 0]], DT, d.u, 0).x;
+      x = posterior.x; P = posterior.P;
+      rows.push({ ...d, ...posterior, prior, dr: dr[0] });
+    }
+    return rows;
+  }
+  function metrics(rows) {
+    const samples = rows.slice(1), fixes = samples.filter(d => d.z !== null);
+    const rmse = (items, value) => items.length ? Math.sqrt(items.reduce((s, d) => s + (value(d) - d.truth) ** 2, 0) / items.length) : null;
+    return { raw: rmse(fixes, d => d.z), filter: rmse(samples, d => d.x[0]), dr: rmse(samples, d => d.dr), fixes: fixes.length,
+      coverage: samples.length ? samples.filter(d => Math.abs(d.x[0] - d.truth) <= 2 * Math.sqrt(d.P[0][0])).length / samples.length : null };
+  }
+  return { DT, STEPS, defaults, predict, correct, seeded, makeData, run, metrics };
+});
