+    console.log(`${scenario} seed 42: raw=${m.raw.toFixed(4)} filter=${m.filter.toFixed(4)} DR=${m.dr.toFixed(4)} coverage=${(100*m.coverage).toFixed(1)}%`);
+  }
+  assert.deepEqual(A.metrics([A.run(A.makeData({}), {})[0]]), { raw: null, filter: null, dr: null, fixes: 0, coverage: null });
+});
